DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('payroll_release_private.release_one(uuid)'::regprocedure) INTO definition; definition:=replace(definition,' INSERT INTO ledger_entries(user_id',' PERFORM set_config(''payroll_release_private.active'',''yes'',true);'||chr(10)||' INSERT INTO ledger_entries(user_id'); EXECUTE definition; END; $$;
CREATE OR REPLACE FUNCTION public.salary_wallet_release_boundary() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF upper(COALESCE(NEW.source_category,''))='SALARY' AND current_setting('payroll_release_private.active',true) IS DISTINCT FROM 'yes' THEN RAISE EXCEPTION 'Salary wallet credits require individual Finance release'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.salary_wallet_release_boundary() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER salary_wallet_release_boundary BEFORE INSERT ON public.ledger_entries FOR EACH ROW EXECUTE FUNCTION public.salary_wallet_release_boundary();